  }
  public void RemoveMembers(WeldGroup group,IEnumerable<string> memberIds){Guard();foreach(var m in group.Members.Where(m=>memberIds.Contains(m.Id)).ToArray()){RemoveMarker(group,m);group.Members.Remove(m);}Save();Document.GraphicsRedraw2();}
  void RemoveMarker(WeldGroup g,WeldMember m){foreach(int decalId in OwnedDecals(g,m).Select(d=>d.DecalID).ToArray())if(!Document.Extension.DeleteDecal(decalId,true))throw new IOException("无法移除本组标牌。");var a=FindMarker(MarkerName(g,m));if(a==null)return;Document.ClearSelection2(true);if(!a.Select3(false,null)||!Document.Extension.DeleteSelection2(0))throw new IOException("无法移除本组标记，请确认装配体可编辑。");}
  public void RemoveGroups(IEnumerable<string> ids){Guard();foreach(var g in Project.Groups.Where(g=>ids.Contains(g.Id)).ToArray()){foreach(var m in g.Members)RemoveMarker(g,m);Project.Groups.Remove(g);}Save();Document.GraphicsRedraw2();}
  public int Highlight(IEnumerable<WeldGroup> groups,IEnumerable<string> members=null){Guard();ClearHighlight();Document.ClearSelection2(true);var mgr=(ISelectionMgr)Document.SelectionManager;var seen=new HashSet<string>();int missing=0,index=0;int[] colors={(int)swUserPreferenceIntegerValue_e.swSystemColorsSelectedItem1,(int)swUserPreferenceIntegerValue_e.swSystemColorsSelectedItem2,(int)swUserPreferenceIntegerValue_e.swSystemColorsSelectedItem3,(int)swUserPreferenceIntegerValue_e.swSystemColorsSelectedItem4,(int)swUserPreferenceIntegerValue_e.swSystemColorsSelectedItem5,(int)swUserPreferenceIntegerValue_e.swSystemColorsSelectedItem6};foreach(var g in groups){int mark=1<<(16+(index++%6));if(!selectionColors.ContainsKey(mark))selectionColors[mark]=mgr.get_SelectionColor(mark);mgr.set_SelectionColor(mark,colors[(index-1)%6]);var data=mgr.CreateSelectData();data.Mark=mark;foreach(var m in g.Members){if(members!=null&&!members.Contains(m.Id))continue;if(!seen.Add(m.Id))continue;var c=Resolve(m);if(c==null){missing++;continue;}if(!c.Select4(true,data,false))missing++;}}Document.GraphicsRedraw2();return missing;}
  public void ClearHighlight(){if(Document==null)return;try{var mgr=(ISelectionMgr)Document.SelectionManager;for(int i=mgr.GetSelectedObjectCount2(-1);i>=1;i--)if(selectionColors.ContainsKey(mgr.GetSelectedObjectMark(i)))mgr.DeSelect2(i,-1);foreach(var pair in selectionColors)mgr.set_SelectionColor(pair.Key,pair.Value);Document.GraphicsRedraw2();}catch(COMException){}selectionColors.Clear();}
  public void HideMembers(IEnumerable<WeldMember> members){Guard();foreach(var m in members){var c=Resolve(m);if(c!=null){if(!hidden.Any(x=>x.Item1.Name2==c.Name2))hidden.Add(Tuple.Create(c,c.Visible));c.Visible=0;}}Document.GraphicsRedraw2();}
  public void RestoreHidden(){foreach(var item in hidden)try{item.Item1.Visible=item.Item2;}catch(COMException){}hidden.Clear();if(Document!=null)try{Document.GraphicsRedraw2();}catch(COMException){}}
  public List<WeldCandidate> Suggest(WeldMember seed,double gapMm,string excluded){Guard();if(gapMm<0||gapMm>10)throw new ArgumentOutOfRangeException("gapMm");var source=Resolve(seed);if(source==null)throw new IOException("基准零件无法解析。");var candidates=new List<WeldCandidate>();var terms=(excluded??"").Split(new[]{',','，',';','；'},StringSplitOptions.RemoveEmptyEntries);var a=source.GetBox(false,false) as double[];if(a==null)throw new IOException("请先解析基准零件。");foreach(var item in ((IAssemblyDoc)Document).GetComponents(false) as object[]??new object[0]){var c=item as IComponent2;if(c==null||c.IsSuppressed()||c.Name2==source.Name2||terms.Any(t=>c.Name2.IndexOf(t.Trim(),StringComparison.OrdinalIgnoreCase)>=0))continue;var model=c.GetModelDoc2() as IModelDoc2;if(model==null||model.GetType()!=1)continue;var b=c.GetBox(false,false) as double[];if(b==null)continue;double lower=0;for(int k=0;k<3;k++){double d=Math.Max(0,Math.Max(a[k]-b[k+3],b[k]-a[k+3]));lower+=d*d;}if(Math.Sqrt(lower)>gapMm/1000+.000001)continue;object pa,pb;double distance=Document.ClosestDistance(source,c,out pa,out pb);if(distance<0||double.IsNaN(distance)||distance>gapMm/1000+.0000001)continue;candidates.Add(new WeldCandidate{Member=Describe(c),GapMm=distance*1000,Reason=distance<.0000001?"接触或相交，需确认焊接关系":"小间隙相邻，需确认焊接关系"});}return candidates.OrderBy(x=>x.GapMm).ThenBy(x=>x.Member.Instance).ToList();}
